import{_ as n,c as a,o as p,ah as l}from"./chunks/framework.DE7iKuik.js";const g=JSON.parse('{"title":"Nginx配置解析","frontmatter":{"title":"Nginx配置解析","createTime":"2023/11/17 15:02:44","permalink":"/article/nginx-config/","lastUpdated":"2026-01-22","tags":[],"link":"/posts/nginx-config","layout":"doc","prev":{"text":"虚拟机配置网络","link":"/posts/network-config"},"next":{"text":"Nginx 配置 WebSocket 代理","link":"/posts/nginx-websocket"}},"headers":[],"params":{"pkg":"nginx-config"},"relativePath":"posts/nginx-config.md","filePath":"posts/[pkg].md"}'),e={name:"posts/nginx-config.md"};function i(c,s,t,o,r,_){return p(),a("div",null,[...s[0]||(s[0]=[l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#==========================nginx全局配置==========================#</span></span>
<span class="line"><span># 指定 nginx 进程运行的用户，这里是 nginx，默认为nobody。</span></span>
<span class="line"><span>user nginx;  </span></span>
<span class="line"><span></span></span>
<span class="line"><span># 指定 nginx 使用多少个 worker 进程处理请求，这里使用了 auto，表示根据 CPU 核心数自动分配。</span></span>
<span class="line"><span>worker_processes auto;  </span></span>
<span class="line"><span></span></span>
<span class="line"><span># 指定 nginx 主进程的 PID 文件路径。</span></span>
<span class="line"><span>pid /run/nginx.pid;  </span></span>
<span class="line"><span></span></span>
<span class="line"><span>#指定错误日志文件的路径</span></span>
<span class="line"><span>error_log /var/log/nginx/error.log;  </span></span>
<span class="line"><span>#==========================nginx全局配置==========================#</span></span>
<span class="line"><span></span></span>
<span class="line"><span>##==========================events==========================##</span></span>
<span class="line"><span># 事件模块的配置</span></span>
<span class="line"><span>events {</span></span>
<span class="line"><span>    # 默认值512,设置每个 worker 进程的最大连接数。</span></span>
<span class="line"><span>    worker_connections  1024;    </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 默认值off,控制是否在一次事件循环中accept多个连接请求。启用 multi_accept 可以减少 CPU 的使用和系统调用的次数，也可能会导致每个请求的响应时间增加</span></span>
<span class="line"><span>    multi_accept on; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 使用连接互斥锁进行顺序的accept()系统调用，防止惊群现象发生，默认为on</span></span>
<span class="line"><span>    accept_mutex on;   </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 如果一个进程没有互斥锁，它将延迟至少多长时间。默认情况下，延迟是500ms </span></span>
<span class="line"><span>    accept_mutex_delay 500ms</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 指定事件驱动模块,默认值select,这个驱动模块在大量连接时，性能较差，这里使用了 epoll。 可选select|poll|kqueue|epoll|resig|/dev/poll|eventport</span></span>
<span class="line"><span>    use epoll;      </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 设置 accept 互斥锁等待时间。</span></span>
<span class="line"><span>    accept_mutex_delay 500ms; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 实验模块，仅在 FreeBSD 下可用,aio 启用则使用异步I/O,不启用则使用同步I/O,默认不启用</span></span>
<span class="line"><span>    aio threads; # 指定异步 I/O 模块，这里使用了 threads。</span></span>
<span class="line"><span>    aio_write on; # 启用异步写入操作。</span></span>
<span class="line"><span>    aio_read on; # 启用异步读取操作。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 事件驱动模块 use epoll时配置</span></span>
<span class="line"><span>    epoll_events 1024; # 默认值为 512，即每次事件循环最多处理 512 个事件。</span></span>
<span class="line"><span>    epoll_event_connections 512; # 默认值为 2048，即每个事件最多处理 2048 个连接。</span></span>
<span class="line"><span>    epoll_timeout 1s; # 默认值为 0，即 epoll 模块不会超时，等待事件的时间取决于操作系统。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //事件驱动模块 use kqueue时配置,仅在 FreeBSD 下可用</span></span>
<span class="line"><span>    kqueue_events 1024;</span></span>
<span class="line"><span>    kqueue_event_connections 512;</span></span>
<span class="line"><span>    kqueue_timeout 1s;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>##==========================events==========================##</span></span>
<span class="line"><span></span></span>
<span class="line"><span>##==========================http==========================##</span></span>
<span class="line"><span># 主要用于处理 HTTP 请求和响应，包括路由、反向代理、缓存、日志等功能。</span></span>
<span class="line"><span>http {</span></span>
<span class="line"><span>    # 导入 MIME 类型的配置文件。</span></span>
<span class="line"><span>    include  /etc/nginx/mime.types;   </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 定义默认的 MIME 类型，默认为text/plain </span></span>
<span class="line"><span>    default_type  application/octet-stream; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 定义访问日志格式 main</span></span>
<span class="line"><span>    log_format main &#39;$remote_addr–$remote_user [$time_local] $request $status $body_bytes_sent $http_referer $http_user_agent $http_x_forwarded_for&#39;; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 指定访问日志文件的路径和格式。</span></span>
<span class="line"><span>    access_log  /var/log/nginx/access.log main; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 指定错误日志文件的路径和格式。</span></span>
<span class="line"><span>    error_log  /var/log/nginx/error.log main;   </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 默认开启,直接把文件内容从磁盘读入内核缓冲区,尤其是在处理大文件时，效果更为明显。</span></span>
<span class="line"><span>    sendfile on;  </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 每个进程每次调用传输数量不能大于设定的值，默认为0，即不设上限。</span></span>
<span class="line"><span>    sendfile_max_chunk 100k;  </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 客户端与服务器之间的连接超时时间，默认值为 75s。</span></span>
<span class="line"><span>    keepalive_timeout 75;  </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 在一个持久连接上最多允许的请求数量，默认值为 100。</span></span>
<span class="line"><span>    keepalive_requests 100; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 是否开启 Gzip 压缩，默认值为 off。</span></span>
<span class="line"><span>    gzip on; </span></span>
<span class="line"><span>    gzip_types text/plain text/css application/json application/javascript application/xml; # 压缩文件类型列表</span></span>
<span class="line"><span>    gzip_min_length 20; # 只压缩大于该长度的文件，单位为字节，默认值为 20。</span></span>
<span class="line"><span>    gzip_buffers 4 8k; # 第一个参数表示缓冲区的数量，第二个参数表示每个缓冲区的大小。 默认值为 4 8k。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 当服务器返回错误码时，可以显示指定的错误页面。</span></span>
<span class="line"><span>    error_page error_page 404 /404.html;  </span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ###==========================upstream=========================###</span></span>
<span class="line"><span>    # upstream 模块用于配置反向代理服务器组，可以将客户端请求转发到多台服务器进行处理，从而实现负载均衡和高可用性。</span></span>
<span class="line"><span>    upstream backend  {   </span></span>
<span class="line"><span>      # 简单的循环负载均衡</span></span>
<span class="line"><span>      server backend1.example.com;</span></span>
<span class="line"><span>      server backend2.example.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 使用权重进行负载平衡</span></span>
<span class="line"><span>      server backend3.example.com weight=3; #指定服务器的权重，缺省为 1，可以是任意正整数。</span></span>
<span class="line"><span>      server backend4.example.com weight=2;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 使用IP Hash值进行权重进行负载平衡,确保来自同一 IP 的请求总是发送到同一服务器。</span></span>
<span class="line"><span>      ip_hash;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 用最少的连接进行负载均衡,动态地将请求发送到最空闲的服务器。</span></span>
<span class="line"><span>      least_conn;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 使用服务器响应时间进行负载平衡,将请求发送到响应时间最短的服务器。</span></span>
<span class="line"><span>      fair;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 根据请求 URL 的哈希值进行负载平衡</span></span>
<span class="line"><span>      hash $remote_addr consistent;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 随机发送到服务器</span></span>
<span class="line"><span>      random;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 为backend分配一个共享内存区域。</span></span>
<span class="line"><span>      zone backend_zone 64k;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 指定与后端服务器的 TCP 连接复用数，缺省为 1。</span></span>
<span class="line"><span>      keepalive 16; </span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 指定与后端服务器的 TCP 连接最大请求数，超过此数量，连接将关闭并重新建立新连接。默认为 100。</span></span>
<span class="line"><span>      keepalive_requests 100;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 指定与后端服务器的 TCP 连接空闲超时时间，默认为 75 秒。</span></span>
<span class="line"><span>      keepalive_timeout 60s;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    ###==========================upstream=========================###</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ###==========================server=========================###</span></span>
<span class="line"><span>    server {</span></span>
<span class="line"><span>      # 监听端口</span></span>
<span class="line"><span>      listen 80;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 指定服务器的主机名。它可以是域名、IP 地址或*匹配任何主机名,也可以配置多个域名</span></span>
<span class="line"><span>      server_name example.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 根目录</span></span>
<span class="line"><span>      root /var/www/example.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 限速 每秒4K</span></span>
<span class="line"><span>      set $limit_rate 4k;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 当用户访问example.com 或 example.com/ 时</span></span>
<span class="line"><span>      location / {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 指定用于提供文件的回退机制。如果请求的文件不存在，nginx将尝试返回fallback</span></span>
<span class="line"><span>        try_files index.html index.htm @fallback;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>      # 上面try files 回退到这里</span></span>
<span class="line"><span>      location @fallback {</span></span>
<span class="line"><span>         root  /var/www/error;</span></span>
<span class="line"><span>         index index.html;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 当用户访问example.com/api时</span></span>
<span class="line"><span>      location /api {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        # 反向代理到 http://backend/api; 本配置中 backend 是个负载均衡器</span></span>
<span class="line"><span>        proxy_pass http://backend/api;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 当用户访问example.com/images时</span></span>
<span class="line"><span>      location /images/ {</span></span>
<span class="line"><span>        # alias 看起来类似于 root 指令，但文档根目录没有改变，只是用于当前请求的路径。 </span></span>
<span class="line"><span>        # /images/top.gif 将返回 /var/www/images/top.gif</span></span>
<span class="line"><span>        alias /var/www/images/;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        # 设置缓存时间为1天,原理是Header 设置Cache-Control</span></span>
<span class="line"><span>        expires 1d;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        # 添加header</span></span>
<span class="line"><span>        add_header Cache-Control &quot;public&quot;;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      location ~ \\.php$ {</span></span>
<span class="line"><span>        include fastcgi_params;  </span></span>
<span class="line"><span>        fastcgi_index index.php;  </span></span>
<span class="line"><span>        # 使用fastcgi协议 转发到 phpfpm的unix socket文件 phpfpm 和 nginx 同一台机器才可以这么配置</span></span>
<span class="line"><span>        fastcgi_pass unix:/var/run/php/php7.x-fpm.sock;</span></span>
<span class="line"><span>        # 使用fastcgi协议 转发到某个服务器某个端口</span></span>
<span class="line"><span>        fastcgi_pass 127.0.0.1:9000;  </span></span>
<span class="line"><span>        # 使用fastcgi协议 转发到负载均衡器</span></span>
<span class="line"><span>        fastcgi_pass http://backend/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        deny 127.0.0.1;  #拒绝的ip</span></span>
<span class="line"><span>        allow 172.18.5.54; #允许的ip           </span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # SSL 配置 监听443</span></span>
<span class="line"><span>      listen 443 ssl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 证书路径</span></span>
<span class="line"><span>      ssl_certificate /etc/ssl/certs/example.com.crt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 证书私钥</span></span>
<span class="line"><span>      ssl_certificate_key /etc/ssl/private/example.com.key;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # HTTP/2 配置 监听443</span></span>
<span class="line"><span>      listen 443 ssl http2;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      # 设置安全header</span></span>
<span class="line"><span>      add_header X-Content-Type-Options &quot;nosniff&quot; always;</span></span>
<span class="line"><span>      add_header X-Frame-Options &quot;SAMEORIGIN&quot; always;</span></span>
<span class="line"><span>      add_header X-XSS-Protection &quot;1; mode=block&quot; always;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    ###==========================server=========================###</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>##==========================http==========================##</span></span></code></pre></div>`,1)])])}const d=n(e,[["render",i]]);export{g as __pageData,d as default};
